css:
:root{--bg:#07111e;--panel:#0d1b2e;--panel2:#11233a;--border:#1f3556;--text:#e6eefc;--text-dim:#c7d6ec;--text-faint:#9cb0cf;--accent:#7c9eff;--accent2:#4fd1c5;--warn:#f5c26b;--sidebar:300px;}
*{box-sizing:border-box}
html{scroll-behavior:smooth;overflow-x:hidden}
body{margin:0;background:var(--bg);color:var(--text);font-family:"Noto Sans JP",-apple-system,"Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,sans-serif;line-height:1.85;font-size:16px;overflow-x:hidden}
a{color:var(--accent);text-decoration:none;overflow-wrap:anywhere}
a:hover{text-decoration:underline}
.layout{display:block}
.sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--sidebar);background:#091524;border-right:1px solid var(--border);overflow-y:auto;padding:24px 16px 40px;z-index:20}
.sidebar .brand{font-size:12px;letter-spacing:.08em;color:var(--accent);font-weight:700;margin:0 8px 14px;text-transform:uppercase}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar li a{display:block;padding:7px 10px;border-radius:8px;color:var(--text-faint);font-size:13.5px;line-height:1.5;border-left:2px solid transparent}
.sidebar li a:hover{background:var(--panel);color:var(--text);text-decoration:none}
.sidebar li a.active{background:var(--panel2);color:#fff;border-left-color:var(--accent)}
.toggle{display:none;position:fixed;top:12px;left:12px;z-index:30;background:var(--panel2);color:var(--text);border:1px solid var(--border);border-radius:10px;padding:8px 12px;font:inherit;font-size:14px;cursor:pointer}
.main{margin-left:var(--sidebar);padding:48px 56px 80px}
.hero{position:relative;overflow:hidden;background:linear-gradient(180deg,#0c1a2e,#0a1626);border:1px solid var(--border);border-radius:16px;padding:36px 36px 28px;margin-bottom:40px}
.hero::before{content:"";position:absolute;top:-120px;right:-80px;width:420px;height:420px;background:radial-gradient(circle,rgba(124,158,255,.22),transparent 65%);pointer-events:none}
.eyebrow{display:inline-block;font-size:12px;font-weight:700;color:var(--accent);background:rgba(124,158,255,.12);border:1px solid rgba(124,158,255,.35);padding:4px 12px;border-radius:999px;letter-spacing:.04em}
.hero-title{font-size:28px;font-weight:800;color:#fff;margin:16px 0 18px;line-height:1.4;position:relative}
.hero-sub{font-size:18px;font-weight:500;color:var(--text-dim)}
.hero-meta{display:grid;grid-template-columns:1.5fr .7fr 1.6fr;position:relative}
.hero-meta>div{padding:2px 22px;border-right:1px solid var(--border);margin:6px 0;min-width:0}
.hero-meta>div:first-child{padding-left:0}.hero-meta>div:last-child{border-right:0}
.ml{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--text-faint)}
.mv{display:block;font-size:14.5px;color:var(--text)}
.hero-links{margin:16px 0 0;padding-top:14px;border-top:1px solid var(--border);font-size:14px;color:var(--text-faint);position:relative}
.hero-links .sep{margin:0 8px;color:var(--border)}
.main h2{font-size:24px;font-weight:800;color:#fff;margin:56px 0 18px;padding:10px 0 10px 16px;border-left:4px solid var(--accent);background:linear-gradient(90deg,rgba(124,158,255,.1),transparent);border-radius:0 8px 8px 0;line-height:1.5;scroll-margin-top:20px}
.main h3{font-size:19px;font-weight:700;color:var(--accent2);margin:34px 0 12px;scroll-margin-top:20px}
.main p{margin:12px 0;color:var(--text-dim)}
.main strong{color:#fff;font-weight:700}
.main ul,.main ol{padding-left:24px;color:var(--text-dim)}
.main li{margin:5px 0}
.main li>p{margin:4px 0}
code{font-family:"JetBrains Mono",Menlo,Consolas,monospace;background:var(--panel2);border:1px solid var(--border);border-radius:5px;padding:1px 6px;font-size:.9em;overflow-wrap:anywhere}
.table-scroll{overflow-x:auto;margin:18px 0;border:1px solid var(--border);border-radius:12px;background:var(--panel)}
table{border-collapse:collapse;width:100%;min-width:560px;font-size:14.5px}
th{background:var(--panel2);color:#fff;text-align:left;font-weight:700;padding:10px 14px;border-bottom:1px solid var(--border);white-space:nowrap}
td{padding:10px 14px;border-bottom:1px solid rgba(31,53,86,.7);vertical-align:top;color:var(--text-dim);line-height:1.7}
tr:last-child td{border-bottom:0}
tbody tr:hover td{background:rgba(124,158,255,.05)}
.callout-stack{margin:18px 0;display:flex;flex-direction:column;gap:12px}
.callout{display:flex;gap:12px;padding:14px 18px;border-radius:12px;border:1px solid var(--border);background:var(--panel)}
.callout-icon{font-size:20px;line-height:1.6;flex:none}
.callout-body{min-width:0}.callout-body p{margin:0;color:var(--text-dim)}
.callout-tip{border-color:rgba(79,209,197,.45);background:rgba(79,209,197,.07)}
.callout-warn{border-color:rgba(245,194,107,.5);background:rgba(245,194,107,.08)}
.callout-note{border-color:rgba(124,158,255,.4);background:rgba(124,158,255,.07)}
.mermaid-diagram{display:block;overflow-x:auto;background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:20px;margin:20px 0}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;flex-shrink:0}
.mermaid-diagram foreignObject{overflow:visible}
.mermaid-diagram foreignObject div,.mermaid-diagram foreignObject span,.mermaid-diagram foreignObject p{white-space:nowrap !important}
.mermaid-diagram p{color:inherit;margin:0}
.checklist-card{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:16px 20px;margin:18px 0}
.checklist-progress{display:flex;align-items:center;gap:12px;margin-bottom:12px;font-size:13px;color:var(--text-faint)}
.cp-bar{flex:1;height:8px;background:var(--panel2);border-radius:99px;overflow:hidden}
.cp-fill{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--accent),var(--accent2));transition:width .25s}
ul.checklist{list-style:none;padding-left:0;margin:0}
ul.checklist li label{display:flex;gap:10px;align-items:flex-start;cursor:pointer}
ul.checklist input{margin-top:7px;accent-color:var(--accent);width:16px;height:16px;flex:none}
.page-footer{margin-top:64px;padding-top:20px;border-top:1px solid var(--border);font-size:13px;color:var(--text-faint)}
@media (max-width:960px){.toggle{display:block}.sidebar{transform:translateX(-100%);transition:transform .25s}.sidebar.open{transform:none}.main{margin-left:0;padding:64px 18px 60px}.hero{padding:24px 18px}.hero-title{font-size:22px}.hero-meta{grid-template-columns:1fr}.hero-meta>div{border-right:0;border-bottom:1px solid var(--border);padding:8px 0;width:100%}.hero-meta>div:last-child{border-bottom:0}}
